from collections import Counter
from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # Repeated, sparse non-background colors mark the corners of output cells.
    limit = max(12, h * w * 0.10)
    points = {}
    for y, row in enumerate(grid):
        for x, v in enumerate(row):
            if v != background and counts[v] <= limit:
                points.setdefault(v, set()).add((y, x))
    rects = []
    for color, pts in points.items():
        ys = sorted({y for y, x in pts})
        xs = sorted({x for y, x in pts})
        for i, y0 in enumerate(ys):
            for y1 in ys[i+1:]:
                for j, x0 in enumerate(xs):
                    for x1 in xs[j+1:]:
                        if {(y0,x0),(y0,x1),(y1,x0),(y1,x1)} <= pts:
                            rects.append((y0,y1,x0,x1,color))
    if not rects:
        return [[background]]
    row_step = 0
    col_step = 0
    for y0,y1,x0,x1,color in rects:
        row_step = gcd(row_step, y1-y0)
        col_step = gcd(col_step, x1-x0)
    rmin = min(r[0] for r in rects); rmax = max(r[1] for r in rects)
    cmin = min(r[2] for r in rects); cmax = max(r[3] for r in rects)
    out = [[background for _ in range((cmax-cmin)//col_step)] for _ in range((rmax-rmin)//row_step)]
    for y0,y1,x0,x1,color in rects:
        out[(y0-rmin)//row_step][(x0-cmin)//col_step] = color
    return out

